const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo(function(result) { resolve(result); }, function(err) { reject(err); });
  });
}

function monthCollection(id, start, end, month) {
  return ee.ImageCollection(id)
    .filterDate(start, end)
    .filter(ee.Filter.calendarRange(month, month, 'month'));
}

function fireSumFromCollection(col) {
  var bin = col.map(function(img) {
    return img.select('FireMask').eq(7).rename('fire');
  });
  return bin.sum().rename('fire');
}

async function monthFireDetections(roi, start, end, month) {
  var mod = monthCollection('MODIS/061/MOD14A1', start, end, month);
  var myd = monthCollection('MODIS/061/MYD14A1', start, end, month);
  var modSize = await getInfoAsync(mod.size());
  var mydSize = await getInfoAsync(myd.size());

  var imgs = [];
  if (modSize > 0) imgs.push(fireSumFromCollection(mod));
  if (mydSize > 0) imgs.push(fireSumFromCollection(myd));

  var usedFallback = false;
  var fbModSize = 0, fbMydSize = 0;

  if (imgs.length === 0) {
    // Fallback to 8-day products
    var mod8 = monthCollection('MODIS/061/MOD14A2', start, end, month);
    var myd8 = monthCollection('MODIS/061/MYD14A2', start, end, month);
    fbModSize = await getInfoAsync(mod8.size());
    fbMydSize = await getInfoAsync(myd8.size());
    if (fbModSize + fbMydSize === 0) {
      return {sum: null, modSize: 0, mydSize: 0, fbModSize: 0, fbMydSize: 0, usedFallback: false};
    }
    usedFallback = true;
    if (fbModSize > 0) imgs.push(fireSumFromCollection(mod8));
    if (fbMydSize > 0) imgs.push(fireSumFromCollection(myd8));
  }

  var fireSumImg = ee.ImageCollection.fromImages(imgs).sum().rename('fire');
  var sumDict = await getInfoAsync(fireSumImg.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }));

  var sum = sumDict ? sumDict.fire : null;
  return {sum: sum, modSize: modSize, mydSize: mydSize, fbModSize: fbModSize, fbMydSize: fbMydSize, usedFallback: usedFallback};
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time
    var countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
    var roi = countries.filter(ee.Filter.eq('country_na', 'Cambodia')).geometry();
    var start = '2014-01-01';
    var end = '2018-01-01';

    // ROI pixel count at 1 km
    var roiPx = await getInfoAsync(ee.Image.constant(1).clip(roi).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: 1000,
      maxPixels: 1e9
    }).get('constant'));
    console.log('ROI 1km pixels:', roiPx);

    // 2. February
    var feb = await monthFireDetections(roi, start, end, 2);
    // 3. October
    var oct = await monthFireDetections(roi, start, end, 10);

    // C1: Empty collections for both primary and fallback in either month
    var febNoData = (feb.sum === null);
    var octNoData = (oct.sum === null);
    console.log('Feb images - MOD14A1:', feb.modSize, 'MYD14A1:', feb.mydSize, feb.usedFallback ? ('(fallback MOD14A2:' + feb.fbModSize + ', MYD14A2:' + feb.fbMydSize + ')') : '');
    console.log('Oct images - MOD14A1:', oct.modSize, 'MYD14A1:', oct.mydSize, oct.usedFallback ? ('(fallback MOD14A2:' + oct.fbModSize + ', MYD14A2:' + oct.fbMydSize + ')') : '');

    if (febNoData || octNoData) {
      console.log('C1: Empty Collection');
      return;
    }

    // 4. Values and validation
    var febSum = feb.sum;
    var octSum = oct.sum;

    console.log('Feb fire detections (px-days):', febSum);
    console.log('Oct fire detections (px-days):', octSum);

    // C3: Calculation failure (null/NaN/invalid)
    var invalid = (febSum === null || octSum === null || !isFinite(febSum) || !isFinite(octSum) || febSum < 0 || octSum < 0);
    if (invalid) {
      console.log('C3: Calculation Failure');
      return;
    }

    // 5. Final Answer
    if (febSum > octSum) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (e) {
    console.log('D: Error');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
